isStandardRequestHeader:
// ─────────────────────────────────────────────────────────
    //  POSTMAN-STYLE HEADERS TABLE
    // ─────────────────────────────────────────────────────────

    private static final Set<String> STANDARD_REQ_HEADERS = Set.of(
        "content-type", "accept", "authorization", "user-agent",
        "cache-control", "accept-encoding", "accept-language",
        "connection", "host", "origin", "referer", "cookie",
        "x-api-key", "x-request-id", "x-correlation-id"
    );

    private static final Set<String> STANDARD_RESP_HEADERS = Set.of(
        "content-type", "content-length", "content-encoding",
        "transfer-encoding", "cache-control", "etag", "date",
        "server", "access-control-allow-origin", "vary",
        "set-cookie", "location", "strict-transport-security",
        "connection", "keep-alive", "x-request-id"
    );

    private boolean isStandardRequestHeader(String key) {
        return key != null && STANDARD_REQ_HEADERS.contains(key.toLowerCase());
    }

isStandardResponseHeader:
private boolean isStandardResponseHeader(String key) {
        return key != null && STANDARD_RESP_HEADERS.contains(key.toLowerCase());
    }

setupPostmanHeadersTable:
private void setupPostmanHeadersTable() {
        headersTable.setEditable(true);
        headersTable.setItems(headersData);

        // ── Col 1: Checkbox (enabled/disabled toggle) ──
        headerEnabledColumn.setCellValueFactory(data -> data.getValue().enabledProperty());
        headerEnabledColumn.setCellFactory(col -> {
            CheckBoxTableCell<KeyValuePair, Boolean> cell = new CheckBoxTableCell<>();
            cell.setAlignment(Pos.CENTER);
            return cell;
        });
        headerEnabledColumn.setEditable(true);

        // ── Col 2: Key — colored for standard headers, inline editable ──
        headerKeyColumn.setCellValueFactory(data -> data.getValue().keyProperty());
        headerKeyColumn.setCellFactory(col -> new TableCell<>() {
            private final TextField tf = new TextField();
            {
                tf.setStyle("-fx-background-color: transparent; -fx-border-color: transparent; -fx-padding: 0 4 0 4;");
                tf.focusedProperty().addListener((obs, wasFocused, isFocused) -> {
                    if (!isFocused && getTableRow() != null && getTableRow().getItem() != null) {
                        getTableRow().getItem().setKey(tf.getText());
                        updateHeaderCountBadge();
                    }
                });
            }
            @Override
            protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) { setGraphic(null); return; }
                tf.setText(item);
                boolean standard = isStandardRequestHeader(item);
                tf.setStyle(
                    "-fx-background-color: transparent; -fx-border-color: transparent; -fx-padding: 0 4 0 4;" +
                    (standard ? " -fx-text-fill: #4f46e5; -fx-font-weight: bold;" : " -fx-text-fill: #1e293b;")
                );
                setGraphic(tf);
                setText(null);
            }
        });
        headerKeyColumn.setEditable(true);

        // ── Col 3: Value — inline editable ──
        headerValueColumn.setCellValueFactory(data -> data.getValue().valueProperty());
        headerValueColumn.setCellFactory(col -> new TableCell<>() {
            private final TextField tf = new TextField();
            {
                tf.setStyle("-fx-background-color: transparent; -fx-border-color: transparent; -fx-padding: 0 4 0 4; -fx-text-fill: #475569;");
                tf.focusedProperty().addListener((obs, wasFocused, isFocused) -> {
                    if (!isFocused && getTableRow() != null && getTableRow().getItem() != null) {
                        getTableRow().getItem().setValue(tf.getText());
                    }
                });
            }
            @Override
            protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) { setGraphic(null); return; }
                tf.setText(item);
                setGraphic(tf);
                setText(null);
            }
        });
        headerValueColumn.setEditable(true);

        // ── Col 4: Delete button per row ──
        headerDeleteColumn.setCellFactory(col -> new TableCell<>() {
            private final Button deleteBtn = new Button("🗑");
            {
                deleteBtn.setStyle(
                    "-fx-background-color: transparent; -fx-border-color: transparent;" +
                    "-fx-text-fill: #94a3b8; -fx-cursor: hand; -fx-font-size: 13px; -fx-padding: 2 4 2 4;"
                );
                deleteBtn.setOnMouseEntered(e -> deleteBtn.setStyle(
                    "-fx-background-color: #fef2f2; -fx-border-color: transparent;" +
                    "-fx-text-fill: #dc2626; -fx-cursor: hand; -fx-font-size: 13px; -fx-padding: 2 4 2 4; -fx-background-radius: 5;"
                ));
                deleteBtn.setOnMouseExited(e -> deleteBtn.setStyle(
                    "-fx-background-color: transparent; -fx-border-color: transparent;" +
                    "-fx-text-fill: #94a3b8; -fx-cursor: hand; -fx-font-size: 13px; -fx-padding: 2 4 2 4;"
                ));
                deleteBtn.setOnAction(e -> {
                    KeyValuePair row = getTableRow().getItem();
                    if (row != null) {
                        headersData.remove(row);
                        updateHeaderCountBadge();
                    }
                });
            }
            @Override
            protected void updateItem(Void v, boolean empty) {
                super.updateItem(v, empty);
                setGraphic(empty ? null : deleteBtn);
            }
        });

        // Count badge live update
        headersData.addListener((ListChangeListener<KeyValuePair>) c -> updateHeaderCountBadge());
        updateHeaderCountBadge();
    }

updateHeaderCountBadge:
private void updateHeaderCountBadge() {
        if (headerCountLabel == null) return;
        int count = headersData.size();
        headerCountLabel.setText(count == 0 ? "No headers" : count + " header" + (count == 1 ? "" : "s"));
        // Update the tab text too
        if (headersTab != null) {
            headersTab.setText(count == 0 ? "Headers" : "Headers (" + count + ")");
        }
    }

